import backtrader as bt


class ReferenceStrategy(bt.Strategy):
    params = (
        ('sma_period', 20),
        ('stop_loss_pct', 0.02),
    )

    def __init__(self):
        self.sma = bt.indicators.SimpleMovingAverage(
            self.data.close, period=self.p.sma_period
        )
        self.order = None
        self.stop_order = None

    def notify_order(self, order):
        if order.status in [order.Submitted, order.Accepted]:
            return

        if order.status in [order.Completed]:
            if order == self.order:
                self.order = None
                if self.position.size != 0 and self.stop_order is None:
                    entry_price = order.executed.price
                    if self.position.size > 0:
                        stop_price = entry_price * (1.0 - self.p.stop_loss_pct)
                        self.stop_order = self.sell(
                            exectype=bt.Order.Stop,
                            price=stop_price,
                            size=abs(self.position.size)
                        )
                    else:
                        stop_price = entry_price * (1.0 + self.p.stop_loss_pct)
                        self.stop_order = self.buy(
                            exectype=bt.Order.Stop,
                            price=stop_price,
                            size=abs(self.position.size)
                        )
            elif order == self.stop_order:
                self.stop_order = None

        elif order.status in [order.Canceled, order.Margin, order.Rejected]:
            if order == self.order:
                self.order = None
            elif order == self.stop_order:
                self.stop_order = None

    def next(self):
        if self.order:
            return

        dt = self.data.datetime.datetime(0)
        weekday = dt.weekday()  # 0 = Monday, 4 = Friday

        # Exit logic
        if self.position.size > 0 and weekday == 4:
            if self.stop_order:
                self.cancel(self.stop_order)
                self.stop_order = None
            self.order = self.close()
            return

        if self.position.size < 0 and weekday == 0:
            if self.stop_order:
                self.cancel(self.stop_order)
                self.stop_order = None
            self.order = self.close()
            return

        # Entry logic
        if not self.position:
            cash = self.broker.getcash()
            price = self.data.close[0]
            comm = getattr(self.broker.getcommissioninfo(self.data).p, 'commission', 0.001)
            size = int(cash / (price * (1.0 + comm)))

            if size > 0:
                if weekday == 0 and price > self.sma[0]:
                    self.order = self.buy(size=size)
                elif weekday == 4 and price < self.sma[0]:
                    self.order = self.sell(size=size)
